int u1 = socket(AF_INET, SOCK_DGRAM, 0);
struct sockaddr_in a1;
memset(&a1, 0, sizeof a1);
a1.sin_family = AF_INET;
a1.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
a1.sin_port = 0;
CHECK_EQ(bind(u1, (struct sockaddr *)&a1, sizeof a1), 0);
char o1[32] = {0};
CHECK_EQ(udp_roundtrip(u1, "x", o1, 32), 1);
